namespace ghidra.features.bsim.gui.filters;







using ghidra.features.bsim.query.client;
using ghidra.features.bsim.query.description;
using ghidra.features.bsim.query.elastic;
using ghidra.features.bsim.query.protocol;

/**
 * A BsimFilterType for filtering on functions in programs created before the filter date.
 */
public class DateEarlierBSimFilterType : DateBSimFilterType {
	public static readonly string XML_VALUE = "dateearlier";

	public DateEarlierBSimFilterType(string sub) : base(sub + " is earlier than", XML_VALUE, "1974-09-21 or 09/21/1974")
    {
	}

	/* @Override */
	public void gatherSQLEffect(SQLEffects effect, FilterAtom atom, IDSQLResolution resolution)
    {
		LocalDate localDate = formatDate(atom.value);
		if (localDate == null) {
			return;
		}
		//localDate is a calendar date, i.e., does not specify hours/minutes/seconds
		//the database records timestamps for executables, so we need to create a timestamp 
		//from localDate.  The timestamp we create corresponds to midnight on localDate
		//*in the system default time zone of the client*.  If an executable's ingest timestamp is
		//before this timestamp, it passes the filter.
		Date date =
			Date.from(localDate.atStartOfDay().atZone(ZoneId.systemDefault()).toInstant());
		effect.setExeTable();
		string dateString =
			new SimpleDateFormat(AbstractSQLFunctionDatabase.JAVA_TIME_FORMAT).format(date);
		StringBuilder buf = new StringBuilder();
		buf.append("exetable.ingest_date < to_timestamp('")
			.append(dateString)
			.append("','" + AbstractSQLFunctionDatabase.SQL_TIME_FORMAT + "')");
		effect.addWhere(this, buf.toString());
	}

	/* @Override */
	public void gatherElasticEffect(ElasticEffects effect, FilterAtom atom,
		IDElasticResolution resolution)
    {
		LocalDate localDate = formatDate(atom.value);
		Date date =
			Date.from(localDate.atStartOfDay().atZone(ZoneId.systemDefault()).toInstant());
		if (date == null) {
			return;
		}

		effect.addDocValue("ZonedDateTime date = doc['ingest_date'].value; ");
		string argName = effect.assignArgument();
		effect.addScriptElement(this, "ZonedDateTime.ofInstant(Instant.ofEpochMilli(params." +
			argName + "), ZoneId.of('Z')).compareTo(date) > 0");
		effect.addDateParam(argName, date);
	}

	/* @Override */
	public bool evaluate(ExecutableRecord rec, string value) {
		LocalDate localDate = formatDate(value);
		Date date =
			Date.from(localDate.atStartOfDay().atZone(ZoneId.systemDefault()).toInstant());
		if (date == null) {
			return true; // Don't filter anything if we can't get a date
		}
		return rec.getDate().before(date);
	}

}
